// Stripe-specific HMAC signature verification.
// Stripe signs webhooks as `t=<timestamp>,v1=<hmac-sha256>`.
// We verify the signature AND a 5-minute replay-window.
//
// Enable by setting STRIPE_WEBHOOK_SECRET (whsec_...) AND
// WEBHOOK_INTEGRITY_CHECK_ENABLED=1.

const secret = $env.STRIPE_WEBHOOK_SECRET;
const integrityCheckEnabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';

if (!secret || !integrityCheckEnabled) {
  return [$input.first()];
}

const crypto = require('crypto');
const item = $input.first();
const rawBody = item.rawBody || '';
const sigHeader = (item.headers && (item.headers['stripe-signature'] || item.headers['Stripe-Signature'])) || '';

if (!sigHeader || !rawBody) {
  throw new Error('UNAUTHORIZED: missing Stripe-Signature or rawBody');
}

// Parse `t=<ts>,v1=<sig>[,v0=<...>]` shape
const pairs = String(sigHeader).split(',').map(p => p.trim());
let timestamp = null;
const v1Sigs = [];
for (const p of pairs) {
  const [k, ...rest] = p.split('=');
  const v = rest.join('=');
  if (k === 't') timestamp = v;
  else if (k === 'v1') v1Sigs.push(v);
}

if (!timestamp || v1Sigs.length === 0) {
  throw new Error('UNAUTHORIZED: malformed Stripe-Signature header');
}

// Replay-window: reject events older than 5 minutes
const REPLAY_WINDOW_S = 300;
const tsNum = parseInt(timestamp, 10);
if (!Number.isFinite(tsNum) || Math.abs(Math.floor(Date.now() / 1000) - tsNum) > REPLAY_WINDOW_S) {
  throw new Error('UNAUTHORIZED: timestamp outside replay window');
}

// Compute expected v1 = HMAC-SHA256(secret, timestamp + '.' + rawBody)
const signedPayload = timestamp + '.' + rawBody;
const expected = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');
const expectedBuf = Buffer.from(expected, 'utf8');

// Constant-time compare against any of the v1 signatures (Stripe rotates)
let match = false;
for (const sig of v1Sigs) {
  if (sig.length !== expected.length) continue;  // length-guard
  const sigBuf = Buffer.from(sig, 'utf8');
  if (crypto.timingSafeEqual(expectedBuf, sigBuf)) {
    match = true;
    break;
  }
}

if (!match) {
  throw new Error('UNAUTHORIZED: invalid signature');
}

return [$input.first()];

// Per-customer-id sliding-window rate limit, opt-in.
// 60 events per 5 minutes per customer. Defends against a leaked
// signing-secret being used to spam events.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return [$input.first()];
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const event = ($input.first().body || {});
const customer = (event.data && event.data.object && event.data.object.customer) || 'unknown';
const key = String(customer);

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a,b) => (a[1][0]||0) - (b[1][0]||0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' events per ' + Math.round(WINDOW_MS / 60000) + ' minutes for customer ' + key);
}
buckets[key] = [...hits, now];

return [$input.first()];

// Idempotency on Stripe event.id. Stripe retries failed webhook deliveries
// up to 3 days. Without dedup we send duplicate Slack messages per retry.

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return [$input.first()];
}

const WINDOW_MS = 24 * 60 * 60 * 1000;  // 24h, Stripe retries within 3d
const MAX_KEYS = 50000;

const event = ($input.first().body || {});
const eventId = event.id;

if (!eventId) {
  return [$input.first()];
}

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a,b) => a[1] - b[1]).slice(0, 5000);
  for (const [k] of oldest) delete seen[k];
}

if (seen[eventId]) {
  return [{ json: { skipped: true, reason: 'duplicate', eventId } }];
}
seen[eventId] = now;

return [$input.first()];

// Normalize the Stripe event into a stable shape for the Slack-message builder.
// Pull customer, amount, plan, status across the supported event types.

const event = ($input.first().body || {});
const type = event.type || 'unknown';
const obj = (event.data && event.data.object) || {};

const customer = obj.customer || obj.customer_email || 'unknown';
const customerEmail = (obj.customer_details && obj.customer_details.email) || obj.customer_email || obj.receipt_email || null;
const customerName = (obj.customer_details && obj.customer_details.name) || null;
const country = (obj.customer_details && obj.customer_details.address && obj.customer_details.address.country) || null;

// Amount in major currency (e.g. EUR, USD)
const amountMinor = obj.amount_total ?? obj.amount_due ?? obj.amount_paid ?? null;
const currency = (obj.currency || 'usd').toUpperCase();
const amount = amountMinor != null ? (amountMinor / 100).toFixed(2) : null;

const plan = (obj.metadata && obj.metadata.plan)
  || (obj.items && obj.items.data && obj.items.data[0] && obj.items.data[0].price && obj.items.data[0].price.nickname)
  || null;

const status = obj.status || obj.payment_status || null;
const subscriptionId = obj.subscription || (obj.id && obj.id.startsWith('sub_') ? obj.id : null);

return [{
  json: {
    eventId: event.id,
    eventType: type,
    customer,
    customerEmail,
    customerName,
    country,
    amount,
    currency,
    plan,
    status,
    subscriptionId,
    livemode: !!event.livemode,
    receivedAt: new Date().toISOString(),
    raw: event,
  },
}];

// Build a Slack Block Kit message tuned per event type.
// Falls through to a generic message for unknown types.

const e = $input.first().json;
const envEmoji = e.livemode ? ':white_check_mark:' : ':warning: TEST';
const customerLine = e.customerName
  ? `${e.customerName} (${e.customerEmail || e.customer})`
  : (e.customerEmail || e.customer);

const amountLine = e.amount ? `*${e.amount} ${e.currency}*` : null;
const planLine = e.plan ? `Plan: *${e.plan}*` : null;

let header = '';
let color = '#36a64f';

switch (e.eventType) {
  case 'checkout.session.completed':
    header = `${envEmoji} New paid customer: ${customerLine}`;
    color = '#36a64f';
    break;
  case 'customer.subscription.created':
    header = `${envEmoji} Subscription started: ${customerLine}`;
    color = '#2eb886';
    break;
  case 'customer.subscription.updated':
    header = `:arrows_counterclockwise: Subscription updated: ${customerLine}`;
    color = '#daa038';
    break;
  case 'customer.subscription.deleted':
    header = `:warning: Subscription cancelled: ${customerLine}`;
    color = '#d93f0b';
    break;
  case 'invoice.payment_failed':
    header = `:rotating_light: Payment failed: ${customerLine}`;
    color = '#a30200';
    break;
  default:
    header = `:bell: Stripe event ${e.eventType}: ${customerLine}`;
    color = '#666666';
    break;
}

const fields = [];
if (amountLine) fields.push({ type: 'mrkdwn', text: amountLine });
if (planLine) fields.push({ type: 'mrkdwn', text: planLine });
if (e.country) fields.push({ type: 'mrkdwn', text: `Country: *${e.country}*` });
if (e.status) fields.push({ type: 'mrkdwn', text: `Status: *${e.status}*` });

const blocks = [
  {
    type: 'section',
    text: { type: 'mrkdwn', text: `*${header}*` },
  },
];

if (fields.length > 0) {
  blocks.push({ type: 'section', fields });
}

blocks.push({
  type: 'context',
  elements: [
    { type: 'mrkdwn', text: `Event \`${e.eventId}\` at ${e.receivedAt}` },
  ],
});

const payload = {
  text: header,  // fallback for notifications
  attachments: [{ color, blocks }],
};

return [{ json: payload }];

// Fallback for Slack webhook failures. Log a structured error and respond
// to Stripe with 200 so Stripe does not retry. (We could also respond 500
// to trigger Stripe retry, but for Slack-delivery failures we accept the
// loss and surface it via the n8n execution log + ops alert.)

const err = ($input.first().json && $input.first().json.error) || {};
const event = ($('Normalize Event').first() && $('Normalize Event').first().json) || {};

return [{
  json: {
    ok: false,
    fallback: true,
    eventId: event.eventId || 'unknown',
    eventType: event.eventType || 'unknown',
    error: {
      message: err.message || 'unknown error',
      name: err.name || 'SlackDeliveryError',
    },
    receivedAt: event.receivedAt || new Date().toISOString(),
  },
}];
